{
  "campaign_title": "Seasonal Refresh: Sustainable Style for Every Wardrobe Transition",
  "business_goal": "Re-engage 57 Seasonal Shoppers by leveraging seasonal collection updates and targeted loyalty incentives across preferred touchpoints to generate incremental repeat purchases within a 30-day campaign window.",
  "target_cohort": "Seasonal Shoppers",
  "projected_revenue_recovery": "€15,000",
  "campaign_pillars": [
    {
      "pillar": "Eco-Conscious Seasonal Drop",
      "description": "Showcase new sustainable, recycled-fabric seasonal apparel featuring inclusive sizing across Womenswear and Menswear to align with Crazy Fashion's core brand values and inspire timely wardrobe updates.",
      "channels": [
        "Email",
        "Mobile App Push",
        "Instagram DM"
      ]
    },
    {
      "pillar": "Crazy Club Tiered Engagement",
      "description": "Activate Silver and Bronze loyalty members through targeted double-points promotions and exclusive early collection access.",
      "channels": [
        "Email",
        "Mobile App Push"
      ]
    },
    {
      "pillar": "Seamless Omnichannel Discovery",
      "description": "Connect digital browsing with physical retail experiences by offering mobile app users exclusive in-store VIP fitting invitations and SMS drop reminders.",
      "channels": [
        "Mobile App Push",
        "SMS",
        "In-Store"
      ]
    }
  ],
  "channel_mix": [
    {
      "channel": "Email",
      "weight": "35%",
      "cadence": "Day 1, Day 5, Day 12"
    },
    {
      "channel": "Mobile App Push",
      "weight": "30%",
      "cadence": "Day 2, Day 7, Day 14"
    },
    {
      "channel": "Instagram DM & Social",
      "weight": "20%",
      "cadence": "Continuous over 14 days, DMs on Day 3 and Day 9"
    },
    {
      "channel": "SMS",
      "weight": "15%",
      "cadence": "Day 1 and Day 10"
    }
  ],
  "ab_testing_hypotheses": [
    "Personalizing email subject lines with customer-preferred category data will increase open rates by >25% compared to generic seasonal titles.",
    "Offering 2x Crazy Club bonus points on eco-friendly capsule collection items will achieve a 20% higher conversion rate among Silver Members than offering a standard 15% promotional discount.",
    "App push notifications linked directly to an interactive, curated Style Lookbook will generate a 30% higher click-through rate than notifications pointing directly to product listing pages."
  ]
}

